window.DCG_CARDS = [
  // ======================= UE 2 — Droit des sociétés =======================
  { id: 'ue2-01', ue: 2, q: 'Capital minimum d\'une SA ?', a: '37 000 €.' },
  { id: 'ue2-02', ue: 2, q: 'Nombre minimum d\'actionnaires d\'une SA non cotée / cotée ?', a: '2 pour une SA non cotée, 7 pour une SA cotée.' },
  { id: 'ue2-03', ue: 2, q: 'Capital minimum d\'une SARL et d\'une SAS ?', a: 'Aucun : le capital est librement fixé par les statuts (1 € possible).' },
  { id: 'ue2-04', ue: 2, q: 'Quelles sont les 3 conditions de fond propres au contrat de société ?', a: 'Les apports, l\'affectio societatis (volonté de collaborer sur un pied d\'égalité) et la participation aux bénéfices et aux pertes.' },
  { id: 'ue2-05', ue: 2, q: 'Quand une société acquiert-elle la personnalité morale ?', a: 'À son immatriculation au RCS. Avant, c\'est une société en formation : les actes passés pour elle engagent leurs auteurs, puis sont repris par la société après l\'immatriculation.' },
  { id: 'ue2-06', ue: 2, q: 'Quelles sont les 3 sortes d\'apports ?', a: 'Apports en numéraire (argent), en nature (biens) et en industrie (travail, savoir-faire). Seuls les apports en numéraire et en nature forment le capital.' },
  { id: 'ue2-07', ue: 2, q: 'Quand un commissaire aux apports est-il obligatoire ?', a: 'Pour les apports en nature en SA. En SARL : si un apport en nature dépasse 30 000 € ou si l\'ensemble des apports en nature dépasse la moitié du capital (sauf décision unanime des associés).' },
  { id: 'ue2-08', ue: 2, q: 'Libération du capital à la constitution : quelle fraction minimum ?', a: 'SARL : au moins 1/5 des apports en numéraire. SA : au moins la moitié. Le solde doit être libéré dans les 5 ans.' },
  { id: 'ue2-09', ue: 2, q: 'SNC : statut des associés et responsabilité ?', a: 'Les associés sont commerçants et responsables indéfiniment et solidairement des dettes sociales (après poursuite préalable de la société). Cession de parts : agrément unanime sauf clause contraire.' },
  { id: 'ue2-10', ue: 2, q: 'Société en commandite : deux catégories d\'associés ?', a: 'Commandités : commerçants, responsabilité indéfinie et solidaire, dirigent. Commanditaires : responsabilité limitée aux apports, ne peuvent pas accomplir d\'actes de gestion externe.' },
  { id: 'ue2-11', ue: 2, q: 'SARL : nombre d\'associés et responsabilité ?', a: 'De 1 (EURL) à 100 associés. Responsabilité limitée aux apports. Gérant : personne physique (associé ou non).' },
  { id: 'ue2-12', ue: 2, q: 'Pouvoirs du gérant de SARL à l\'égard des tiers ?', a: 'Il peut accomplir tous actes de gestion dans l\'intérêt de la société. Les limitations statutaires de pouvoirs sont inopposables aux tiers (sauf acte étranger à l\'objet social si le tiers le savait).' },
  { id: 'ue2-13', ue: 2, q: 'SARL : règles de cession de parts à un tiers ?', a: 'Agrément préalable à la majorité des associés représentant au moins la moitié des parts sociales. Cessions entre associés, au conjoint, ascendants ou descendants : libres sauf clause contraire.' },
  { id: 'ue2-14', ue: 2, q: 'SARL : majorités des décisions collectives ?', a: 'Ordinaires : plus de la moitié des parts (à défaut, majorité des votes émis à la 2e consultation). Extraordinaires (modification des statuts) : 3/4 des parts. Approbation des comptes : dans les 6 mois de la clôture.' },
  { id: 'ue2-15', ue: 2, q: 'SA : deux modes d\'organisation de la direction ?', a: 'Conseil d\'administration (3 à 18 membres) avec un PDG ou une dissociation président/directeur général ; ou directoire (2 à 5 membres, 7 si cotée) et conseil de surveillance (3 à 18 membres).' },
  { id: 'ue2-16', ue: 2, q: 'SA : quorum et majorité de l\'AGO et de l\'AGE ?', a: 'AGO : quorum 1/5 des actions à la 1re convocation (aucun à la 2e), majorité des voix exprimées. AGE : quorum 1/4 (1/5 à la 2e), majorité des 2/3 des voix des actionnaires présents ou représentés.' },
  { id: 'ue2-17', ue: 2, q: 'Quelle est la compétence de l\'AGO et celle de l\'AGE ?', a: 'AGO : approbation des comptes, affectation du résultat, nomination et révocation des administrateurs et commissaires aux comptes. AGE : modification des statuts (capital, objet, siège...).' },
  { id: 'ue2-18', ue: 2, q: 'Durée du mandat d\'un commissaire aux comptes ?', a: '6 exercices. Il certifie les comptes, est obligatoire en SA, et en SARL/SAS si deux des trois seuils (bilan, chiffre d\'affaires, effectif) sont dépassés (à vérifier selon l\'année).' },
  { id: 'ue2-19', ue: 2, q: 'SAS : caractéristiques essentielles ?', a: 'Grande liberté statutaire, capital libre, pas de limite du nombre d\'associés, président obligatoire (personne physique ou morale), pas d\'offre au public de titres financiers. SASU : un seul associé.' },
  { id: 'ue2-20', ue: 2, q: 'Quelle est la procédure des conventions réglementées en SA ?', a: 'Autorisation préalable du conseil, rapport spécial du commissaire aux comptes, puis approbation par l\'AG des actionnaires (l\'intéressé ne vote pas). Les conventions courantes conclues à des conditions normales échappent à la procédure.' },
  { id: 'ue2-21', ue: 2, q: 'Réserve légale : règle de dotation ?', a: 'On prélève 5 % du bénéfice de l\'exercice (diminué des pertes antérieures) jusqu\'à ce que la réserve atteigne 10 % du capital.' },
  { id: 'ue2-22', ue: 2, q: 'Bénéfice distribuable ?', a: 'Bénéfice de l\'exercice − pertes antérieures − dotation à la réserve légale + report à nouveau bénéficiaire (+ réserves disponibles). Aucune distribution si les capitaux propres deviendraient inférieurs au capital augmenté des réserves non distribuables.' },
  { id: 'ue2-23', ue: 2, q: 'Capitaux propres inférieurs à la moitié du capital : que faire ?', a: 'Le dirigeant convoque l\'assemblée dans les 4 mois de l\'approbation des comptes pour décider de la dissolution anticipée. Si elle est rejetée, la société doit régulariser au plus tard à la clôture du 2e exercice suivant.' },
  { id: 'ue2-24', ue: 2, q: 'Quels sont les trois modes d\'augmentation de capital ?', a: 'Apports nouveaux (numéraire ou nature), incorporation de réserves/bénéfices/primes, conversion de créances. En SA, droit préférentiel de souscription des actionnaires.' },
  { id: 'ue2-25', ue: 2, q: 'Abus de majorité, de minorité et d\'égalité ?', a: 'Abus de majorité : décision contraire à l\'intérêt social prise dans le seul intérêt des majoritaires. Abus de minorité : blocage contraire à l\'intérêt social dans le seul intérêt des minoritaires. Abus d\'égalité : même chose entre deux groupes à 50/50.' },
  { id: 'ue2-26', ue: 2, q: 'Responsabilités des dirigeants ?', a: 'Civile (faute de gestion, action sociale au nom de la société ou action individuelle d\'un tiers/associé), pénale (abus de biens sociaux, présentation de comptes inexacts) et en cas de procédure collective (insuffisance d\'actif).' },
  { id: 'ue2-27', ue: 2, q: 'Quels sont les effets d\'une fusion ?', a: 'Transmission universelle du patrimoine de la société absorbée à l\'absorbante et dissolution sans liquidation de l\'absorbée ; ses associés reçoivent des titres de l\'absorbante.' },
  { id: 'ue2-28', ue: 2, q: 'Causes de dissolution d\'une société ?', a: 'Arrivée du terme, réalisation ou extinction de l\'objet, annulation, dissolution anticipée décidée par les associés, jugement, perte de pluralité (régularisation possible sous 1 an), pertes ≥ moitié du capital (si décidée).' },
  { id: 'ue2-29', ue: 2, q: 'Société civile (ex. SCI) : régime de responsabilité ?', a: 'Les associés répondent indéfiniment des dettes sociales, mais non solidairement : chacun à proportion de ses parts, après poursuite préalable infructueuse de la société.' },
  { id: 'ue2-30', ue: 2, q: 'Différence entre pacte d\'associés et statuts ?', a: 'Les statuts sont publiés et opposables à tous. Le pacte d\'associés est un contrat confidentiel entre associés, qui n\'engage qu\'eux (clauses de préemption, de sortie conjointe, de non-concurrence...).' },

  // ======================= UE 4 — Droit fiscal =======================
  { id: 'ue4-01', ue: 4, q: 'Taux normal de l\'impôt sur les sociétés (IS) ?', a: '25 %. Taux réduit de 15 % jusqu\'à 42 500 € de bénéfice pour les PME remplissant les conditions (CA < 10 M€, capital entièrement libéré et détenu à 75 % au moins par des personnes physiques).' },
  { id: 'ue4-02', ue: 4, q: 'Taux de TVA en France métropolitaine ?', a: 'Taux normal 20 %, taux réduits 10 % et 5,5 %, taux super-réduit 2,1 %.' },
  { id: 'ue4-03', ue: 4, q: 'Fait générateur et exigibilité de la TVA : vente de biens vs prestation de services ?', a: 'Biens : fait générateur et exigibilité = livraison. Services : fait générateur = exécution de la prestation, exigibilité = encaissement (sauf option pour les débits).' },
  { id: 'ue4-04', ue: 4, q: 'Différence entre impôt direct et indirect ?', a: 'L\'impôt direct est payé directement par le contribuable qui le supporte (IR, IS). L\'impôt indirect est supporté par le consommateur mais reversé par un intermédiaire (TVA).' },
  { id: 'ue4-05', ue: 4, q: 'Calcul du résultat fiscal d\'une société à l\'IS ?', a: 'Résultat comptable + réintégrations extra-comptables (charges non déductibles) − déductions extra-comptables (produits non imposables) = résultat fiscal (− déficits reportés).' },
  { id: 'ue4-06', ue: 4, q: 'Conditions de déductibilité d\'une charge ?', a: 'Charge engagée dans l\'intérêt de l\'exploitation, effective et appuyée de justificatifs, comptabilisée au cours de l\'exercice qu\'elle concerne, non exclue par un texte (amendes, IS, dépenses somptuaires...).' },
  { id: 'ue4-07', ue: 4, q: 'Quelles sont les 4 dates d\'acomptes d\'IS ?', a: '15 mars, 15 juin, 15 septembre et 15 décembre (pour un exercice calé sur l\'année civile). Le solde est payé le 15 du 5e mois suivant la clôture.' },
  { id: 'ue4-08', ue: 4, q: 'Report des déficits à l\'IS ?', a: 'Report en avant sans limite de durée, imputé sur les bénéfices futurs dans la limite de 1 M€ + 50 % de la fraction du bénéfice excédant 1 M€. Option possible pour un report en arrière (1 an, plafonné à 1 M€).' },
  { id: 'ue4-09', ue: 4, q: 'Régime mère-fille : conditions et effet ?', a: 'Participation d\'au moins 5 % du capital, titres conservés 2 ans. Les dividendes reçus sont exonérés d\'IS, sauf une quote-part de frais et charges de 5 % réintégrée.' },
  { id: 'ue4-10', ue: 4, q: 'Intégration fiscale : condition de détention et effet ?', a: 'La mère détient au moins 95 % du capital des filiales. Le résultat d\'ensemble est la somme algébrique des résultats de chaque société ; l\'IS est payé par la société mère.' },
  { id: 'ue4-11', ue: 4, q: 'Plus-values professionnelles : court terme et long terme ?', a: 'Court terme : immobilisation détenue moins de 2 ans (ou amortissements réintégrés) → imposée avec le résultat courant. Long terme : détenue depuis 2 ans ou plus → régime de faveur (taux réduit pour entreprises à l\'IR, exonérations possibles sous conditions).' },
  { id: 'ue4-12', ue: 4, q: 'Mécanisme de la TVA ?', a: 'Impôt sur la consommation par paiement fractionné : chaque entreprise collecte la TVA sur ses ventes et déduit celle de ses achats. TVA à payer = TVA collectée − TVA déductible (ou crédit de TVA).' },
  { id: 'ue4-13', ue: 4, q: 'Conditions de déduction de la TVA ?', a: 'Le bien ou service doit être utilisé pour des opérations imposables, la TVA doit figurer sur une facture régulière au nom de l\'entreprise, et la TVA ne doit pas être exclue du droit à déduction (ex. véhicules de tourisme, essence selon les cas).' },
  { id: 'ue4-14', ue: 4, q: 'Régimes d\'imposition à la TVA ?', a: 'Franchise en base (pas de TVA ni de déduction, sous des seuils de chiffre d\'affaires à vérifier selon l\'année), régime simplifié (acomptes + déclaration annuelle), régime réel normal (déclaration mensuelle ou trimestrielle).' },
  { id: 'ue4-15', ue: 4, q: 'TVA : opérations exonérées avec ou sans droit à déduction ?', a: 'Exonérations avec droit à déduction : exportations et livraisons intracommunautaires. Exonérations sans droit à déduction : opérations de santé, enseignement, assurances, location nue de locaux d\'habitation, opérations bancaires.' },
  { id: 'ue4-16', ue: 4, q: 'Acquisition intracommunautaire de biens : comment traiter la TVA ?', a: 'Autoliquidation : l\'acquéreur déclare la TVA collectée et déduit en même temps la TVA déductible sur sa déclaration (opération neutre si droit à déduction complet).' },
  { id: 'ue4-17', ue: 4, q: 'Quelles sont les catégories de revenus de l\'IR ?', a: 'Traitements et salaires, BIC, BNC, BA (bénéfices agricoles), revenus fonciers, revenus de capitaux mobiliers, plus-values (mobilières et immobilières).' },
  { id: 'ue4-18', ue: 4, q: 'Quotient familial : nombre de parts ?', a: 'Célibataire : 1 part. Couple marié/pacsé : 2 parts. 0,5 part par enfant pour les deux premiers, 1 part à partir du 3e. Impôt = (impôt sur le revenu/nb de parts) × nb de parts, avec plafonnement de l\'avantage.' },
  { id: 'ue4-19', ue: 4, q: 'Régimes micro : abattements forfaitaires ?', a: 'Micro-BIC : 71 % (vente de marchandises), 50 % (prestations de services). Micro-BNC : 34 %. Régimes soumis à des seuils de chiffre d\'affaires (à vérifier selon l\'année).' },
  { id: 'ue4-20', ue: 4, q: 'Revenus fonciers : régimes d\'imposition ?', a: 'Micro-foncier : abattement de 30 %, loyers bruts ≤ 15 000 €/an. Régime réel : déduction des charges réelles (intérêts, travaux, taxe foncière, assurance...) ; déficit imputable sur le revenu global dans une limite de 10 700 € (hors intérêts).' },
  { id: 'ue4-21', ue: 4, q: 'Délai de reprise de l\'administration fiscale ?', a: '3 ans (jusqu\'au 31 décembre de la 3e année suivant celle de l\'imposition). 10 ans en cas d\'activité occulte ; prolongations en cas de contrôle ou de manœuvres frauduleuses.' },
  { id: 'ue4-22', ue: 4, q: 'Sanctions fiscales : intérêts de retard et majorations ?', a: 'Intérêt de retard : 0,20 % par mois. Majorations : 10 % retard de déclaration/paiement, 40 % manquement délibéré, 80 % manœuvres frauduleuses ou abus de droit.' },
  { id: 'ue4-23', ue: 4, q: 'Déroulement d\'une vérification de comptabilité ?', a: 'Avis de vérification (délai de 2 jours minimum avant le début), contrôle sur place (3 mois maximum pour les PME), proposition de rectification motivée, délai de réponse du contribuable de 30 jours, débat oral et contradictoire, mise en recouvrement.' },
  { id: 'ue4-24', ue: 4, q: 'Principes fondamentaux du droit fiscal ?', a: 'Légalité de l\'impôt (voté par le Parlement, art. 34 de la Constitution), annualité, non-rétroactivité, égalité devant l\'impôt, consentement à l\'impôt, interprétation stricte de la loi.' },
  { id: 'ue4-25', ue: 4, q: 'Qu\'est-ce que l\'abus de droit fiscal ?', a: 'Acte fictif ou acte à but exclusivement fiscal qui, tout en respectant les textes, va à l\'encontre de leur objet ; l\'administration l\'écarte et applique une majoration (80 %, ou 40 % en cas de bonne foi).' },
  { id: 'ue4-26', ue: 4, q: 'Qu\'est-ce que le rescrit fiscal ?', a: 'Une prise de position formelle de l\'administration sur l\'application de la loi fiscale à une situation précise ; elle est opposable à l\'administration.' },
  { id: 'ue4-27', ue: 4, q: 'Voies de contestation d\'un impôt ?', a: 'Réclamation contentieuse auprès de l\'administration (dans un délai qui expire le 31 décembre de la 2e année suivant la mise en recouvrement) puis recours devant le tribunal administratif (impôts directs, TVA).' },
  { id: 'ue4-28', ue: 4, q: 'Impôts locaux professionnels : CFE et taxe foncière ?', a: 'La CFE (cotisation foncière des entreprises) est due par les entreprises dans chaque commune où elles ont des locaux, selon la valeur locative. La taxe foncière est due par le propriétaire d\'un bien immobilier.' },

  // ======================= UE 6 — Finance d'entreprise =======================
  { id: 'ue6-01', ue: 6, q: 'Formule du fonds de roulement net global (FRNG) ?', a: 'FRNG = Ressources stables − Emplois stables (haut de bilan) ou = Actif circulant − Dettes à court terme (bas de bilan).' },
  { id: 'ue6-02', ue: 6, q: 'Formule du BFR d\'exploitation ?', a: 'BFR = Actif circulant d\'exploitation (stocks + créances clients) − Passif circulant d\'exploitation (dettes fournisseurs, fiscales et sociales).' },
  { id: 'ue6-03', ue: 6, q: 'Relation entre FRNG, BFR et trésorerie nette ?', a: 'Trésorerie nette = FRNG − BFR.' },
  { id: 'ue6-04', ue: 6, q: 'Comment calcule-t-on la VAN d\'un investissement ?', a: 'VAN = Σ flux nets de trésorerie actualisés − capital investi. Un projet est rentable si VAN > 0.' },
  { id: 'ue6-05', ue: 6, q: 'Qu\'est-ce que la capacité d\'autofinancement (CAF) ?', a: 'Ressource interne issue de l\'activité : résultat net + dotations − reprises + valeur nette comptable des éléments cédés − produits des cessions. Autofinancement = CAF − dividendes.' },
  { id: 'ue6-06', ue: 6, q: 'CAF : méthode soustractive à partir de l\'EBE ?', a: 'CAF = EBE + autres produits encaissables − autres charges décaissables ± produits et charges financiers encaissables/décaissables − impôt sur les bénéfices.' },
  { id: 'ue6-07', ue: 6, q: 'Ratios de liquidité ?', a: 'Générale = actif circulant ÷ dettes à court terme. Réduite = (créances + disponibilités) ÷ dettes à court terme. Immédiate = disponibilités ÷ dettes à court terme.' },
  { id: 'ue6-08', ue: 6, q: 'Ratios de structure financière ?', a: 'Autonomie financière = capitaux propres ÷ total des dettes (ou ÷ total du passif pour l\'indépendance). Capacité de remboursement = dettes financières ÷ CAF (en années).' },
  { id: 'ue6-09', ue: 6, q: 'Calcul des délais de rotation (clients, fournisseurs, stocks) ?', a: 'Délai clients = créances clients TTC ÷ CA TTC × 360 (ou 365). Délai fournisseurs = dettes fournisseurs TTC ÷ achats TTC × 360. Rotation des stocks = stock moyen ÷ coût d\'achat des ventes × 360.' },
  { id: 'ue6-10', ue: 6, q: 'Rentabilité économique et rentabilité financière ?', a: 'Rentabilité économique = résultat d\'exploitation (après impôt) ÷ capitaux investis (actif économique). Rentabilité financière = résultat net ÷ capitaux propres.' },
  { id: 'ue6-11', ue: 6, q: 'Effet de levier financier ?', a: 'Rf = Re + (Re − i) × D/CP, avec Re rentabilité économique, i coût de la dette, D dettes financières, CP capitaux propres. L\'endettement améliore la rentabilité financière si Re > i.' },
  { id: 'ue6-12', ue: 6, q: 'Les 3 flux d\'un tableau de flux de trésorerie ?', a: 'Flux de trésorerie d\'exploitation, d\'investissement et de financement. Leur somme explique la variation de trésorerie de l\'exercice.' },
  { id: 'ue6-13', ue: 6, q: 'Formule d\'actualisation ?', a: 'Valeur actuelle = Flux ÷ (1 + t)^n, avec t le taux d\'actualisation et n l\'année du flux. Le coefficient d\'actualisation est (1 + t)^-n.' },
  { id: 'ue6-14', ue: 6, q: 'Flux de trésorerie d\'un projet d\'investissement ?', a: 'Flux = (produits encaissables − charges décaissables) × (1 − taux d\'IS) + dotation aux amortissements × taux d\'IS − variation du BFR. En fin de projet : valeur résiduelle nette d\'impôt et récupération du BFR.' },
  { id: 'ue6-15', ue: 6, q: 'Qu\'est-ce que le taux de rentabilité interne (TRI) ?', a: 'Le taux d\'actualisation pour lequel la VAN est nulle. Un projet est accepté si TRI > coût du capital (taux exigé).' },
  { id: 'ue6-16', ue: 6, q: 'Délai de récupération du capital investi (DRCI) ?', a: 'Durée nécessaire pour que les flux cumulés (actualisés ou non) égalent le capital investi. Critère de liquidité, qui ne tient pas compte des flux après le délai.' },
  { id: 'ue6-17', ue: 6, q: 'Indice de profitabilité (IP) ?', a: 'IP = valeur actuelle des flux ÷ capital investi (= 1 + VAN ÷ capital investi). Un projet est rentable si IP > 1 ; utile pour classer des projets de tailles différentes.' },
  { id: 'ue6-18', ue: 6, q: 'Annuité constante d\'un emprunt ?', a: 'a = V0 × i ÷ (1 − (1 + i)^-n). Intérêts = capital restant dû × i ; amortissement du capital = annuité − intérêts ; les amortissements forment une progression géométrique de raison (1 + i).' },
  { id: 'ue6-19', ue: 6, q: 'Emprunt à amortissement constant ?', a: 'Amortissement du capital = V0 ÷ n chaque année ; les intérêts diminuent, donc les annuités sont décroissantes.' },
  { id: 'ue6-20', ue: 6, q: 'Taux proportionnel et taux équivalent ?', a: 'Taux proportionnel mensuel = taux annuel ÷ 12. Taux équivalent mensuel = (1 + taux annuel)^(1/12) − 1 ; c\'est celui qui conserve la capitalisation annuelle.' },
  { id: 'ue6-21', ue: 6, q: 'Coût moyen pondéré du capital (CMPC / WACC) ?', a: 'CMPC = CP/(CP + D) × coût des capitaux propres + D/(CP + D) × coût de la dette × (1 − taux d\'IS).' },
  { id: 'ue6-22', ue: 6, q: 'MEDAF : formule du coût des capitaux propres ?', a: 'E(Ri) = Rf + β × (E(Rm) − Rf), avec Rf taux sans risque, β sensibilité du titre au marché, E(Rm) − Rf prime de risque du marché.' },
  { id: 'ue6-23', ue: 6, q: 'Modèle de Gordon-Shapiro ?', a: 'Valeur d\'une action = D1 ÷ (k − g), avec D1 prochain dividende, k rendement exigé et g taux de croissance constant du dividende (k > g).' },
  { id: 'ue6-24', ue: 6, q: 'Théorème de Modigliani-Miller ?', a: 'Sans impôt ni coûts de faillite, la valeur de l\'entreprise ne dépend pas de sa structure financière. Avec impôt, la dette augmente la valeur grâce à l\'économie d\'impôt sur les intérêts.' },
  { id: 'ue6-25', ue: 6, q: 'Plan de financement : principe ?', a: 'Tableau pluriannuel qui équilibre les emplois (investissements, remboursements, dividendes, variation du BFR) et les ressources (CAF, apports, emprunts, cessions) pour assurer l\'équilibre financier.' },
  { id: 'ue6-26', ue: 6, q: 'Budget de trésorerie vs plan de financement ?', a: 'Le budget de trésorerie est à court terme (mensuel, sur un an) et suit les encaissements et décaissements. Le plan de financement est à moyen/long terme et prépare le financement des investissements.' },
  { id: 'ue6-27', ue: 6, q: 'Comment comparer un crédit-bail et un emprunt ?', a: 'On compare la valeur actuelle des décaissements nets (annuités/redevances, économies d\'IS sur charges, valeur résiduelle ou levée d\'option) actualisés au coût de la dette après impôt. Le moins cher est préférable.' },
  { id: 'ue6-28', ue: 6, q: 'Méthodes d\'évaluation d\'une entreprise ?', a: 'Patrimoniale (actif net comptable corrigé), par les flux (DCF : flux de trésorerie actualisés + valeur terminale), par les multiples/comparables (PER = cours ÷ bénéfice par action, multiples d\'EBE).' },
  { id: 'ue6-29', ue: 6, q: 'Principales sources de financement ?', a: 'Fonds propres (apports, autofinancement), quasi-fonds propres (comptes courants, titres participatifs), dettes (emprunts bancaires, obligations), financements court terme (découvert, escompte, affacturage).' },
  { id: 'ue6-30', ue: 6, q: 'Seuil de rentabilité ou VAN : quand un taux d\'actualisation plus élevé fait-il baisser la VAN ?', a: 'Toujours pour un projet classique (décaissement initial puis flux positifs) : plus t est élevé, plus les flux futurs sont dévalorisés. Si t = TRI, la VAN s\'annule.' },

  // ======================= UE 7 — Management =======================
  { id: 'ue7-01', ue: 7, q: 'Taylor : principes de l\'organisation scientifique du travail (OST) ?', a: 'Division horizontale (parcellisation des tâches) et verticale (séparation conception/exécution), étude des temps et mouvements, rémunération au rendement, sélection et formation des ouvriers. Critique : déshumanisation.' },
  { id: 'ue7-02', ue: 7, q: 'Fayol : fonctions de l\'entreprise et éléments de l\'administration ?', a: 'Six fonctions : technique, commerciale, financière, de sécurité, comptable, administrative. Administrer = prévoir, organiser, commander, coordonner, contrôler.' },
  { id: 'ue7-03', ue: 7, q: 'Weber : la bureaucratie ?', a: 'Organisation rationnelle-légale : division du travail, hiérarchie, règles écrites impersonnelles, recrutement sur compétence, carrière. Garantit l\'équité et la prévisibilité mais peut devenir rigide.' },
  { id: 'ue7-04', ue: 7, q: 'Mayo : école des relations humaines ?', a: 'Expériences de Hawthorne : la productivité dépend aussi de facteurs psychosociaux (attention portée aux salariés, groupe informel), pas seulement des conditions matérielles et de la rémunération.' },
  { id: 'ue7-05', ue: 7, q: 'Les 5 niveaux de besoins de Maslow ?', a: 'Physiologiques, sécurité, appartenance (sociaux), estime, accomplissement de soi. On vise un niveau supérieur quand l\'inférieur est satisfait.' },
  { id: 'ue7-06', ue: 7, q: 'Herzberg : théorie des deux facteurs ?', a: 'Facteurs d\'hygiène (salaire, conditions de travail, relations) : leur absence démotive mais leur présence ne motive pas. Facteurs de motivation (reconnaissance, responsabilité, contenu du travail) : ils motivent.' },
  { id: 'ue7-07', ue: 7, q: 'McGregor : théories X et Y ?', a: 'Théorie X : l\'individu n\'aime pas travailler, il faut le contrôler et le sanctionner. Théorie Y : l\'individu s\'investit s\'il est motivé et autonome, le management doit favoriser l\'initiative.' },
  { id: 'ue7-08', ue: 7, q: 'Mintzberg : les 5 composantes de l\'organisation ?', a: 'Sommet stratégique, ligne hiérarchique, centre opérationnel, technostructure (analystes), fonctions de support logistique.' },
  { id: 'ue7-09', ue: 7, q: 'Mintzberg : les 5 configurations structurelles ?', a: 'Structure simple, bureaucratie mécaniste, bureaucratie professionnelle, structure divisionnalisée, adhocratie. Chacune combine une composante clé et un mécanisme de coordination dominant.' },
  { id: 'ue7-10', ue: 7, q: 'Mintzberg : mécanismes de coordination ?', a: 'Ajustement mutuel, supervision directe, standardisation des procédés, des résultats, des qualifications (et des normes).' },
  { id: 'ue7-11', ue: 7, q: 'Les 3 niveaux de stratégie ?', a: 'Stratégie d\'entreprise/de groupe (corporate : quels métiers ?), stratégie d\'activité (business : comment s\'y battre ?), stratégies fonctionnelles (production, marketing, RH, finance).' },
  { id: 'ue7-12', ue: 7, q: 'Les 6 dimensions du PESTEL ?', a: 'Politique, Économique, Socioculturel, Technologique, Écologique, Légal : analyse de l\'environnement général de l\'entreprise.' },
  { id: 'ue7-13', ue: 7, q: 'Les 5 forces concurrentielles de Porter ?', a: 'Rivalité entre concurrents existants, menace des nouveaux entrants, menace des produits de substitution, pouvoir de négociation des clients, pouvoir de négociation des fournisseurs.' },
  { id: 'ue7-14', ue: 7, q: 'Chaîne de valeur de Porter ?', a: 'Activités principales : logistique interne, production, logistique externe, commercialisation et vente, services. Activités de soutien : infrastructure, GRH, recherche-développement, approvisionnement. La marge = valeur créée − coûts.' },
  { id: 'ue7-15', ue: 7, q: 'Compétences distinctives et ressources stratégiques ?', a: 'Ressources et compétences rares, de valeur, difficiles à imiter et à substituer qui donnent un avantage concurrentiel durable (approche par les ressources, RBV).' },
  { id: 'ue7-16', ue: 7, q: 'Que signifie SWOT ?', a: 'Strengths (forces), Weaknesses (faiblesses), Opportunities (opportunités), Threats (menaces) : diagnostic interne (forces/faiblesses) et externe (opportunités/menaces).' },
  { id: 'ue7-17', ue: 7, q: 'Matrice BCG : les 4 catégories ?', a: 'Vedettes (forte croissance, part relative forte), vaches à lait (faible croissance, part forte), dilemmes/points d\'interrogation (forte croissance, part faible), poids morts (faible croissance, part faible).' },
  { id: 'ue7-18', ue: 7, q: 'Les 3 stratégies génériques de Porter ?', a: 'Domination par les coûts, différenciation, concentration (focalisation sur un segment, par les coûts ou la différenciation).' },
  { id: 'ue7-19', ue: 7, q: 'Matrice d\'Ansoff ?', a: 'Croisement produits (actuels/nouveaux) × marchés (actuels/nouveaux) : pénétration, développement de marché, développement de produit, diversification.' },
  { id: 'ue7-20', ue: 7, q: 'Les modes de croissance de l\'entreprise ?', a: 'Interne (investissement organique), externe (fusion, acquisition, prise de participation), conjointe (alliance, partenariat, joint-venture, franchise).' },
  { id: 'ue7-21', ue: 7, q: 'Diversification, intégration verticale, externalisation ?', a: 'Diversification : nouveaux produits/marchés (liée ou conglomérale). Intégration verticale : en amont (fournisseurs) ou en aval (distribution). Externalisation : confier une activité à un prestataire pour se recentrer sur son cœur de métier.' },
  { id: 'ue7-22', ue: 7, q: 'Structures fonctionnelle, divisionnelle, matricielle ?', a: 'Fonctionnelle : regroupement par fonction. Divisionnelle : par produit, zone ou client, avec autonomie des divisions. Matricielle : double rattachement (fonction et projet), flexible mais source de conflits d\'autorité.' },
  { id: 'ue7-23', ue: 7, q: 'Les 3 niveaux de la culture d\'entreprise (Schein) ?', a: 'Artefacts (visibles : locaux, rites, vocabulaire), valeurs affichées, hypothèses de base (croyances implicites partagées, plus profondes).' },
  { id: 'ue7-24', ue: 7, q: 'Types de pouvoir (French et Raven) ?', a: 'Pouvoir de récompense, coercitif, légitime (position), de référence (charisme) et d\'expertise ; l\'autorité est un pouvoir légitime.' },
  { id: 'ue7-25', ue: 7, q: 'Styles de leadership ?', a: 'Lewin : autoritaire, démocratique, laisser-faire. Blake et Mouton : grille entre intérêt pour la production et pour les hommes. Hersey et Blanchard : style adapté à la maturité des collaborateurs (théorie situationnelle).' },
  { id: 'ue7-26', ue: 7, q: 'Simon : la rationalité limitée et le processus de décision ?', a: 'Le décideur ne dispose pas d\'une information complète et choisit une solution satisfaisante plutôt qu\'optimale. Processus IMC : intelligence (identifier le problème), modélisation (solutions), choix.' },
  { id: 'ue7-27', ue: 7, q: 'Lewin : les 3 étapes du changement ?', a: 'Décristallisation (remise en cause des habitudes), changement (déplacement vers la nouvelle situation), recristallisation (stabilisation). Il faut gérer les résistances au changement.' },
  { id: 'ue7-28', ue: 7, q: 'Les 10 rôles du manager de Mintzberg ?', a: 'Trois familles : interpersonnels (figure de proue, leader, agent de liaison), informationnels (observateur, diffuseur, porte-parole), décisionnels (entrepreneur, régulateur, répartiteur de ressources, négociateur).' },
  { id: 'ue7-29', ue: 7, q: 'Qu\'est-ce que la GPEC ?', a: 'Gestion prévisionnelle des emplois et des compétences : anticiper l\'écart entre besoins futurs et ressources humaines (recrutement, formation, mobilité) en cohérence avec la stratégie.' },
  { id: 'ue7-30', ue: 7, q: 'RSE et parties prenantes ?', a: 'La responsabilité sociétale des entreprises intègre dans la stratégie les enjeux économiques, sociaux et environnementaux. Parties prenantes (Freeman) : acteurs influencés par l\'entreprise ou l\'influençant (actionnaires, salariés, clients, fournisseurs, État, ONG...).' },
  { id: 'ue7-31', ue: 7, q: 'Théorie de l\'agence : problème et solutions ?', a: 'Conflit d\'intérêts entre mandants (actionnaires) et mandataires (dirigeants), avec asymétrie d\'information. Solutions : contrôle (audit, conseil d\'administration), incitation (stock-options, bonus), obligations de transparence.' },
  { id: 'ue7-32', ue: 7, q: 'Les étapes du management stratégique ?', a: 'Diagnostic stratégique (externe et interne), choix stratégiques (options, évaluation selon pertinence, faisabilité, acceptabilité), mise en œuvre (organisation, ressources, budgets), contrôle et ajustements.' },

  // ======================= UE 10 — Comptabilité approfondie =======================
  { id: 'ue10-01', ue: 10, q: 'Principe d\'indépendance des exercices ?', a: 'Chaque exercice comptabilise uniquement ses charges et produits : on enregistre les charges constatées d\'avance, produits constatés d\'avance, charges à payer et produits à recevoir.' },
  { id: 'ue10-02', ue: 10, q: 'Principe de prudence ?', a: 'Ne pas comptabiliser de produits non réalisés, mais provisionner les risques et pertes probables (dépréciations, provisions).' },
  { id: 'ue10-03', ue: 10, q: 'Différence entre amortissement et dépréciation ?', a: 'L\'amortissement constate la perte de valeur certaine et irréversible (usure, obsolescence). La dépréciation constate une perte de valeur probable et réversible.' },
  { id: 'ue10-04', ue: 10, q: 'Quand constitue-t-on une provision pour risques et charges ?', a: 'Quand il existe une obligation à l\'égard d\'un tiers, dont il est probable ou certain qu\'elle provoquera une sortie de ressources sans contrepartie au moins équivalente, et dont le montant est estimable avec fiabilité. Dotation : 6815, reprise : 7815.' },
  { id: 'ue10-05', ue: 10, q: 'Résultat de cession d\'une immobilisation ?', a: 'Prix de cession − Valeur nette comptable (VNC). Plus-value si positif, moins-value si négatif. VNC = valeur d\'origine − amortissements cumulés.' },
  { id: 'ue10-06', ue: 10, q: 'Principes comptables fondamentaux ?', a: 'Prudence, continuité d\'exploitation, permanence des méthodes, indépendance des exercices, intangibilité du bilan d\'ouverture, coût historique, non-compensation, image fidèle.' },
  { id: 'ue10-07', ue: 10, q: 'Qu\'est-ce qu\'une immobilisation (PCG) ?', a: 'Un actif identifiable (séparable ou issu de droits légaux/contractuels), contrôlé par l\'entité, destiné à servir de façon durable (plus d\'un exercice) et dont on attend des avantages économiques futurs.' },
  { id: 'ue10-08', ue: 10, q: 'Coût d\'entrée d\'une immobilisation acquise ?', a: 'Prix d\'achat net des remises et rabais + droits de douane et taxes non récupérables + coûts directement attribuables (transport, installation, honoraires). Immobilisation produite : coût de production.' },
  { id: 'ue10-09', ue: 10, q: 'Approche par composants ?', a: 'Chaque élément d\'une immobilisation ayant une durée d\'utilisation différente est comptabilisé et amorti séparément (ex. gros œuvre, toiture, ascenseur d\'un immeuble).' },
  { id: 'ue10-10', ue: 10, q: 'Amortissement linéaire : formule et prorata temporis ?', a: 'Annuité = base amortissable ÷ durée d\'utilisation (taux = 1 ÷ durée). La première annuité est calculée prorata temporis de la date de mise en service (en mois ou en jours).' },
  { id: 'ue10-11', ue: 10, q: 'Coefficients de l\'amortissement dégressif ?', a: '1,25 si durée de 3 ou 4 ans · 1,75 si 5 ou 6 ans · 2,25 si plus de 6 ans. Taux dégressif = taux linéaire × coefficient, appliqué à la VNC. On passe au linéaire quand l\'annuité linéaire sur la durée restante devient supérieure.' },
  { id: 'ue10-12', ue: 10, q: 'Amortissement dérogatoire : définition et compte ?', a: 'Écart entre l\'amortissement fiscal (dégressif, exceptionnel) et l\'amortissement économique (pour durée d\'utilité) : dotation 6872, reprise 7872, compte 145 « amortissements dérogatoires » au passif (provisions réglementées).' },
  { id: 'ue10-13', ue: 10, q: 'Dépréciation d\'une immobilisation : quand ?', a: 'S\'il existe un indice de perte de valeur et que la valeur actuelle (la plus élevée de la valeur vénale et de la valeur d\'usage) devient inférieure à la VNC. Dotation : 6816, comptes 29.' },
  { id: 'ue10-14', ue: 10, q: 'Traitement d\'un client douteux ?', a: 'Reclassement : débit 416 Clients douteux / crédit 411 (TTC). Dépréciation de la perte probable, calculée sur le HT : débit 6817 / crédit 491. Si perte définitive : débit 654 (HT) et 44571 (TVA) / crédit 416 ; reprise de la dépréciation.' },
  { id: 'ue10-15', ue: 10, q: 'Évaluation et dépréciation des stocks ?', a: 'Évaluation au coût d\'acquisition ou de production (CMUP ou PEPS/FIFO ; DEPS interdit). Dépréciation si valeur d\'inventaire (valeur actuelle) inférieure au coût : comptes 39, dotation 6817, reprise 7817.' },
  { id: 'ue10-16', ue: 10, q: 'Variation de stocks de marchandises : sens des écritures ?', a: 'Stock initial annulé : débit 6037 / crédit 37. Stock final constaté : débit 37 / crédit 6037. Si SF > SI, 6037 est créditeur (la variation diminue les charges).' },
  { id: 'ue10-17', ue: 10, q: 'Charges constatées d\'avance et produits constatés d\'avance ?', a: 'CCA : charge payée sur l\'exercice mais relative au suivant (compte 486, à l\'actif). PCA : produit encaissé d\'avance mais relatif au suivant (compte 487, au passif). Régularisées en début d\'exercice suivant par extourne.' },
  { id: 'ue10-18', ue: 10, q: 'Charges à payer et produits à recevoir ?', a: 'Charges à payer : factures non parvenues (408 pour des fournisseurs, 4286/4386... pour le personnel et les organismes sociaux). Produits à recevoir : produits acquis mais non encore facturés (418, 4287...).' },
  { id: 'ue10-19', ue: 10, q: 'Écritures de cession d\'une immobilisation ?', a: '1) Dotation complémentaire jusqu\'à la date de cession. 2) Produit : débit 462 ou 512 / crédit 775 (prix de cession HT) et 44571 (TVA). 3) Sortie : débit 28x (amortissements cumulés) et 675 (VNC) / crédit 2x (valeur d\'origine).' },
  { id: 'ue10-20', ue: 10, q: 'Emprunt : écriture d\'intérêts courus à la clôture ?', a: 'Débit 66116 Intérêts des emprunts / crédit 1688 Intérêts courus (prorata temporis du dernier échéancier). Extourne au début de l\'exercice suivant.' },
  { id: 'ue10-21', ue: 10, q: 'Subvention d\'investissement : comptabilisation ?', a: 'Reçue en capitaux propres (131), puis quote-part virée au résultat chaque année au rythme de l\'amortissement du bien subventionné : débit 139 / crédit 777.' },
  { id: 'ue10-22', ue: 10, q: 'Crédit-bail : traitement dans les comptes sociaux et en consolidation ?', a: 'Comptes individuels : redevances en charges (612), engagement hors bilan. En consolidation : retraitement en immobilisation amortie et en dette financière (comme si le bien était acquis à crédit).' },
  { id: 'ue10-23', ue: 10, q: 'Augmentation de capital par apports en numéraire : écritures ?', a: 'Souscription : débit 456 / crédit 101 Capital souscrit non appelé (ou 1011/1012) et 1041 Prime d\'émission. Libération : débit 512 / crédit 456. Les frais d\'augmentation s\'imputent sur la prime d\'émission ou s\'inscrivent en charges.' },
  { id: 'ue10-24', ue: 10, q: 'Affectation du résultat : ordre des opérations ?', a: '1) Imputation des pertes antérieures (report à nouveau). 2) Dotation à la réserve légale (5 %, jusqu\'à 10 % du capital). 3) Réserves statutaires. 4) Dividendes. 5) Autres réserves. 6) Report à nouveau du solde.' },
  { id: 'ue10-25', ue: 10, q: 'Écriture de l\'affectation du résultat (bénéfice) ?', a: 'Débit 120 Résultat de l\'exercice (bénéfice) / Crédit 1061 Réserve légale, 457 Associés – dividendes à payer, 1068 Autres réserves, 110 Report à nouveau créditeur.' },
  { id: 'ue10-26', ue: 10, q: 'Opérations en devises : conversion à la clôture ?', a: 'Créances et dettes en devises sont converties au cours de clôture. Écart de conversion actif (476, perte latente) et passif (477, gain latent) ; une provision pour perte de change (1515) est constituée à hauteur des pertes latentes (écart de conversion actif).' },
  { id: 'ue10-27', ue: 10, q: 'Charge d\'impôt sur les sociétés : écritures ?', a: 'Acomptes payés : débit 444 / crédit 512. À la clôture : débit 695 Impôts sur les bénéfices / crédit 444 État – impôts sur les bénéfices (IS dû). Le solde à payer est le compte 444 créditeur après acomptes.' },
  { id: 'ue10-28', ue: 10, q: 'Les trois documents des comptes annuels ?', a: 'Bilan, compte de résultat et annexe. Trois systèmes : base (petites entités), abrégé, développé (grandes entités).' },
  { id: 'ue10-29', ue: 10, q: 'Soldes intermédiaires de gestion : de la marge commerciale à l\'EBE ?', a: 'Marge commerciale = ventes de marchandises − coût d\'achat des marchandises vendues. Valeur ajoutée = marge commerciale + production de l\'exercice − consommations en provenance de tiers. EBE = VA + subventions d\'exploitation − impôts et taxes − charges de personnel.' },
  { id: 'ue10-30', ue: 10, q: 'Consolidation : critères de contrôle et méthode associée ?', a: 'Contrôle exclusif (plus de 50 % des droits de vote, ou présomption à plus de 40 % si aucun autre associé ne détient davantage) → intégration globale. Contrôle conjoint → intégration proportionnelle. Influence notable (présumée à partir de 20 % des droits de vote) → mise en équivalence.' },
  { id: 'ue10-31', ue: 10, q: 'Étapes de la consolidation par intégration globale ?', a: 'Retraitements d\'homogénéisation, cumul des comptes, élimination des opérations intragroupe, élimination des titres contre la quote-part de capitaux propres (écart d\'acquisition), partage des capitaux propres entre groupe et intérêts minoritaires.' },
  { id: 'ue10-32', ue: 10, q: 'Écart d\'acquisition et intérêts minoritaires ?', a: 'Écart d\'acquisition = prix d\'acquisition des titres − quote-part dans la juste valeur de l\'actif net identifiable (goodwill, positif ou négatif). Intérêts minoritaires = quote-part des capitaux propres et du résultat de la filiale détenue par les tiers.' },

  // ======================= UE 11 — Contrôle de gestion =======================
  { id: 'ue11-01', ue: 11, q: 'Formule de la marge sur coût variable (MCV) ?', a: 'MCV = Chiffre d\'affaires − Charges variables. Taux de MCV = MCV ÷ CA.' },
  { id: 'ue11-02', ue: 11, q: 'Formule du seuil de rentabilité (en valeur) ?', a: 'SR = Charges fixes ÷ Taux de MCV. En quantité : Charges fixes ÷ MCV unitaire.' },
  { id: 'ue11-03', ue: 11, q: 'Comment calcule-t-on la marge de sécurité ?', a: 'Marge de sécurité = CA − Seuil de rentabilité (ou en % : (CA − SR) ÷ CA = indice de sécurité).' },
  { id: 'ue11-04', ue: 11, q: 'Que sont les charges incorporables et les charges supplétives ?', a: 'Charges incorporables = charges de la comptabilité générale retenues dans les coûts. Charges supplétives = charges non comptabilisées mais intégrées aux coûts (ex. rémunération de l\'exploitant).' },
  { id: 'ue11-05', ue: 11, q: 'Coût de production d\'un produit fini ?', a: 'Coût d\'achat des matières consommées + charges directes de production (MOD) + charges indirectes de production.' },
  { id: 'ue11-06', ue: 11, q: 'Rôle du contrôle de gestion ?', a: 'Piloter la performance : fixer des objectifs, suivre les résultats, mesurer les écarts et aider à décider. Critères : pertinence (objectifs adaptés), efficacité (atteindre les objectifs), efficience (au moindre coût).' },
  { id: 'ue11-07', ue: 11, q: 'Anthony : les 3 niveaux de contrôle ?', a: 'Planification stratégique (long terme, direction), contrôle de gestion (moyen terme, responsables : s\'assurer que les ressources sont utilisées efficacement), contrôle opérationnel (court terme : exécution des tâches).' },
  { id: 'ue11-08', ue: 11, q: 'Charges directes et indirectes ?', a: 'Directes : affectables sans ambiguïté à un coût (matières, MOD d\'un produit). Indirectes : communes à plusieurs coûts, réparties par clés ou unités d\'œuvre.' },
  { id: 'ue11-09', ue: 11, q: 'Méthode des centres d\'analyse (sections homogènes) : étapes ?', a: '1) Répartition primaire des charges indirectes entre sections. 2) Répartition secondaire des sections auxiliaires sur les principales (prestations réciproques résolues par un système d\'équations). 3) Calcul du coût de l\'unité d\'œuvre.' },
  { id: 'ue11-10', ue: 11, q: 'Coût d\'achat, coût de production, coût de revient ?', a: 'Coût d\'achat = prix d\'achat + charges d\'achat. Coût de production = matières consommées + MOD + charges de production. Coût de revient = coût de production des produits vendus + charges de distribution (+ administration).' },
  { id: 'ue11-11', ue: 11, q: 'Comment valoriser les sorties de stock : CMUP et FIFO ?', a: 'CMUP : coût moyen unitaire pondéré = (stock initial + entrées) ÷ (quantités initiales + entrées), en fin de période ou après chaque entrée. FIFO/PEPS : on sort d\'abord les unités les plus anciennes.' },
  { id: 'ue11-12', ue: 11, q: 'Imputation rationnelle des charges fixes ?', a: 'Coefficient d\'imputation = activité réelle ÷ activité normale. Charges fixes imputées = charges fixes réelles × coefficient. Le coût de sous-activité (ou boni de suractivité) est la différence : charges fixes non imputées.' },
  { id: 'ue11-13', ue: 11, q: 'Direct costing simple et évolué ?', a: 'Simple : seules les charges variables sont imputées aux coûts (MCV). Évolué : on distingue aussi les charges fixes spécifiques (marge sur coût spécifique) des charges fixes communes (non réparties).' },
  { id: 'ue11-14', ue: 11, q: 'Levier opérationnel (degré de levier) ?', a: 'Levier opérationnel = MCV ÷ Résultat d\'exploitation = 1 ÷ indice de sécurité. Mesure la sensibilité du résultat à une variation du chiffre d\'affaires : +1 % de CA donne +levier % de résultat.' },
  { id: 'ue11-15', ue: 11, q: 'Point mort : définition ?', a: 'Date à laquelle le seuil de rentabilité est atteint : (SR ÷ CA annuel) × 12 mois (ou × 360 jours), en supposant une activité régulière.' },
  { id: 'ue11-16', ue: 11, q: 'Méthode ABC (Activity-Based Costing) ?', a: 'Les charges indirectes sont regroupées par activités, puis imputées aux produits selon des inducteurs de coût (ex. nombre de lancements). Elle fait mieux apparaître le lien charges/consommation de ressources.' },
  { id: 'ue11-17', ue: 11, q: 'Coût cible (target costing) ?', a: 'On part du prix de vente accepté par le marché : coût cible = prix de vente − marge souhaitée. On conçoit ensuite le produit pour respecter ce coût.' },
  { id: 'ue11-18', ue: 11, q: 'Chaîne des budgets de l\'exploitation ?', a: 'Budget des ventes → budget de production (production = ventes + stock final − stock initial) → budget des approvisionnements (achats = besoins + stock final − stock initial) → budgets de charges (MOD, frais généraux) → budget de trésorerie.' },
  { id: 'ue11-19', ue: 11, q: 'Budget de trésorerie : construction ?', a: 'Tableau mensuel des encaissements (ventes avec délais clients, TVA collectée...) et décaissements (achats avec délais fournisseurs, salaires, TVA, impôts, investissements...). Solde = trésorerie cumulée, comparée aux découverts autorisés.' },
  { id: 'ue11-20', ue: 11, q: 'Écart global et sens de l\'écart ?', a: 'Écart = résultat (ou coût) réel − prévu. Pour une charge, écart positif = défavorable ; pour un produit ou une marge, écart positif = favorable.' },
  { id: 'ue11-21', ue: 11, q: 'Écarts sur matières premières : prix et quantité ?', a: 'Écart sur prix = (Pr − Ps) × Qr. Écart sur quantité = (Qr − Qs) × Ps. Qs = quantité standard pour la production réelle. Écart global = coût réel − coût standard.' },
  { id: 'ue11-22', ue: 11, q: 'Écarts sur main-d\'œuvre directe : taux et temps ?', a: 'Écart sur taux = (Tr − Ts) × Hr. Écart sur temps (rendement) = (Hr − Hs) × Ts, avec Hs les heures standard pour la production réelle.' },
  { id: 'ue11-23', ue: 11, q: 'Écarts sur charges indirectes : budget, activité, rendement ?', a: 'Écart sur budget = coût réel − budget flexible de l\'activité réelle. Écart sur activité = budget flexible − coût imputé à l\'activité réelle (sous/suractivité des charges fixes). Écart sur rendement = différence entre activité réelle et activité standard.' },
  { id: 'ue11-24', ue: 11, q: 'Écarts sur chiffre d\'affaires et sur marge ?', a: 'Sur CA : écart sur prix = (Pr − Ps) × Qr ; écart sur quantité = (Qr − Qs) × Ps. Sur marge : écart sur marge unitaire × Qr + écart sur quantité (volume) × marge unitaire standard.' },
  { id: 'ue11-25', ue: 11, q: 'Tableau de bord : caractéristiques ?', a: 'Outil de pilotage à court terme avec peu d\'indicateurs pertinents, comparés à des objectifs, présentés régulièrement à un responsable pour déclencher des actions correctives.' },
  { id: 'ue11-26', ue: 11, q: 'Balanced scorecard : quatre axes ?', a: 'Axe financier, axe clients, axe processus internes, axe apprentissage organisationnel (innovation, compétences). Relie la stratégie aux indicateurs de performance.' },
  { id: 'ue11-27', ue: 11, q: 'Centres de responsabilité ?', a: 'Centre de coûts (maîtrise des charges), de profit (charges et produits), d\'investissement (rentabilité des capitaux engagés : ROI ou résultat résiduel).' },
  { id: 'ue11-28', ue: 11, q: 'Prix de cession interne : méthodes ?', a: 'Au coût (variable ou complet, avec ou sans marge), au prix du marché, négocié entre centres. Doit éviter les conflits et favoriser l\'optimum du groupe.' },
  { id: 'ue11-29', ue: 11, q: 'ROI et résultat résiduel pour un centre d\'investissement ?', a: 'ROI = résultat ÷ capitaux investis. Résultat résiduel = résultat − (capitaux investis × taux de rendement exigé) ; il évite de refuser un projet rentable mais de rendement inférieur au ROI actuel.' },
  { id: 'ue11-30', ue: 11, q: 'Quand abandonner un produit ?', a: 'On compare la marge sur coût spécifique du produit (et non son résultat en coût complet). On l\'abandonne si cette marge est négative ou si les charges fixes spécifiques évitées dépassent sa MCV, sans possibilité de réaffecter les ressources.' }
];

window.DCG_QCM = [
  // ---- UE 2 ----
  { id: 'q-ue2-01', ue: 2, q: 'Quel est le capital minimum d\'une SA ?', choices: ['1 €', '8 000 €', '37 000 €', '100 000 €'], answer: 2, expl: 'Le capital minimum d\'une société anonyme est de 37 000 €.' },
  { id: 'q-ue2-02', ue: 2, q: 'Dans une SARL, la responsabilité des associés est…', choices: ['Illimitée et solidaire', 'Limitée aux apports', 'Illimitée mais non solidaire', 'Limitée au double des apports'], answer: 1, expl: 'Les associés de SARL ne supportent les pertes qu\'à concurrence de leurs apports.' },
  { id: 'q-ue2-03', ue: 2, q: 'Quelle majorité faut-il pour modifier les statuts d\'une SARL ?', choices: ['Plus de la moitié des parts', '2/3 des voix exprimées', '3/4 des parts sociales', 'L\'unanimité'], answer: 2, expl: 'Les décisions extraordinaires en SARL exigent les 3/4 des parts sociales.' },
  { id: 'q-ue2-04', ue: 2, q: 'En SA, quelle est la majorité requise en AGE ?', choices: ['Majorité simple des voix exprimées', '2/3 des voix des actionnaires présents ou représentés', '3/4 du capital', 'L\'unanimité'], answer: 1, expl: 'L\'assemblée générale extraordinaire statue à la majorité des 2/3 des voix des actionnaires présents ou représentés.' },
  { id: 'q-ue2-05', ue: 2, q: 'Capital 100 000 €, réserve légale 8 000 €, bénéfice 60 000 €. Quelle dotation à la réserve légale ?', choices: ['3 000 €', '2 000 €', '5 000 €', '6 000 €'], answer: 1, expl: '5 % de 60 000 = 3 000, mais la réserve est plafonnée à 10 % du capital = 10 000 : il ne manque que 2 000 €.' },
  { id: 'q-ue2-06', ue: 2, q: 'Quelle société impose à ses associés commerçants une responsabilité indéfinie et solidaire ?', choices: ['SARL', 'SAS', 'SNC', 'SA'], answer: 2, expl: 'Dans une société en nom collectif, les associés sont commerçants et répondent indéfiniment et solidairement des dettes.' },
  { id: 'q-ue2-07', ue: 2, q: 'Les capitaux propres d\'une société tombent à moins de la moitié du capital. Dans quel délai les dirigeants consultent-ils les associés ?', choices: ['1 mois', '4 mois après l\'approbation des comptes', '6 mois après la clôture', '2 ans'], answer: 1, expl: 'Les associés doivent décider dans les 4 mois qui suivent l\'approbation des comptes de la dissolution anticipée éventuelle.' },
  { id: 'q-ue2-08', ue: 2, q: 'Dans une SAS, quel organe est légalement obligatoire ?', choices: ['Un conseil d\'administration', 'Un président', 'Un directoire', 'Un conseil de surveillance'], answer: 1, expl: 'La SAS doit désigner un président ; le reste de l\'organisation relève de la liberté statutaire.' },
  { id: 'q-ue2-09', ue: 2, q: 'À partir de quand une société a-t-elle la personnalité morale ?', choices: ['Signature des statuts', 'Dépôt du capital', 'Immatriculation au RCS', 'Première facture'], answer: 2, expl: 'La personnalité morale s\'acquiert à l\'immatriculation au registre du commerce et des sociétés.' },
  { id: 'q-ue2-10', ue: 2, q: 'Quel est le nombre maximum d\'associés d\'une SARL ?', choices: ['50', '100', '150', 'Illimité'], answer: 1, expl: 'Une SARL compte de 1 à 100 associés.' },
  { id: 'q-ue2-11', ue: 2, q: 'Un apport en nature en SARL nécessite un commissaire aux apports si sa valeur dépasse…', choices: ['5 000 €', '10 000 €', '30 000 €', '100 000 €'], answer: 2, expl: 'Au-delà de 30 000 € (ou si les apports en nature dépassent la moitié du capital), un commissaire aux apports est requis sauf décision unanime des associés.' },
  { id: 'q-ue2-12', ue: 2, q: 'Quel est l\'effet d\'une fusion-absorption sur la société absorbée ?', choices: ['Liquidation puis partage', 'Dissolution sans liquidation', 'Changement de forme', 'Aucun effet'], answer: 1, expl: 'Son patrimoine est transmis en bloc à l\'absorbante et elle est dissoute sans liquidation.' },

  // ---- UE 4 ----
  { id: 'q-ue4-01', ue: 4, q: 'Quel est le taux normal de TVA en France métropolitaine ?', choices: ['5,5 %', '10 %', '19,6 %', '20 %'], answer: 3, expl: 'Taux normal : 20 %. Les taux réduits sont 10 %, 5,5 % et 2,1 %.' },
  { id: 'q-ue4-02', ue: 4, q: 'La TVA est un impôt…', choices: ['Direct sur le revenu', 'Indirect sur la consommation', 'Direct sur le patrimoine', 'Sur les bénéfices'], answer: 1, expl: 'Elle est supportée par le consommateur final et reversée à l\'État par les entreprises.' },
  { id: 'q-ue4-03', ue: 4, q: 'Bénéfice de 100 000 d\'une PME éligible au taux réduit. IS dû ?', choices: ['15 000 €', '20 750 €', '25 000 €', '21 250 €'], answer: 1, expl: '42 500 × 15 % = 6 375 ; (100 000 − 42 500) × 25 % = 14 375 ; total 20 750 €.' },
  { id: 'q-ue4-04', ue: 4, q: 'Résultat comptable 80 000 ; réintégrations 12 000 ; déductions 5 000. Résultat fiscal ?', choices: ['73 000 €', '87 000 €', '97 000 €', '63 000 €'], answer: 1, expl: '80 000 + 12 000 − 5 000 = 87 000 €.' },
  { id: 'q-ue4-05', ue: 4, q: 'TVA collectée 12 000 €, TVA déductible 7 500 €. TVA à décaisser ?', choices: ['19 500 €', '7 500 €', '4 500 €', '12 000 €'], answer: 2, expl: '12 000 − 7 500 = 4 500 €.' },
  { id: 'q-ue4-06', ue: 4, q: 'Quel taux de TVA s\'applique, en principe, à la restauration sur place ?', choices: ['2,1 %', '5,5 %', '10 %', '20 %'], answer: 2, expl: 'La restauration sur place est soumise au taux réduit de 10 %.' },
  { id: 'q-ue4-07', ue: 4, q: 'Quelle participation minimale ouvre droit au régime mère-fille ?', choices: ['5 % du capital', '10 % du capital', '50 % du capital', '95 % du capital'], answer: 0, expl: 'Au moins 5 % du capital de la filiale, conservés 2 ans ; 95 % est le seuil de l\'intégration fiscale.' },
  { id: 'q-ue4-08', ue: 4, q: 'Combien de parts de quotient familial pour un couple marié avec 2 enfants ?', choices: ['2', '2,5', '3', '4'], answer: 2, expl: '2 parts pour le couple + 0,5 × 2 enfants = 3 parts.' },
  { id: 'q-ue4-09', ue: 4, q: 'Un manquement délibéré entraîne une majoration de…', choices: ['10 %', '20 %', '40 %', '80 %'], answer: 2, expl: '10 % pour retard, 40 % pour manquement délibéré, 80 % pour manœuvres frauduleuses ou abus de droit.' },
  { id: 'q-ue4-10', ue: 4, q: 'Pour une prestation de services, la TVA est exigible…', choices: ['À la livraison', 'À l\'encaissement', 'À la commande', 'À la clôture de l\'exercice'], answer: 1, expl: 'Pour les prestations de services, l\'exigibilité est à l\'encaissement (sauf option pour les débits).' },
  { id: 'q-ue4-11', ue: 4, q: 'Quels sont les mois des acomptes d\'IS ?', choices: ['Mars, juin, septembre, décembre', 'Janvier, avril, juillet, octobre', 'Février, mai, août, novembre', 'Juin et décembre uniquement'], answer: 0, expl: 'Les acomptes sont versés les 15 mars, 15 juin, 15 septembre et 15 décembre.' },
  { id: 'q-ue4-12', ue: 4, q: 'Quel est le délai normal de reprise de l\'administration fiscale ?', choices: ['1 an', '3 ans', '6 ans', '10 ans'], answer: 1, expl: 'Jusqu\'à la fin de la 3e année suivant l\'imposition ; 10 ans en cas d\'activité occulte.' },
  { id: 'q-ue4-13', ue: 4, q: 'Quelle charge n\'est PAS déductible du résultat fiscal ?', choices: ['Les salaires', 'Les loyers', 'Les amendes pénales', 'Les intérêts d\'emprunt'], answer: 2, expl: 'Les amendes et pénalités n\'ont pas le caractère de charge engagée dans l\'intérêt de l\'exploitation : elles sont réintégrées.' },
  { id: 'q-ue4-14', ue: 4, q: 'Le seuil de détention pour l\'intégration fiscale est de…', choices: ['50 %', '75 %', '90 %', '95 %'], answer: 3, expl: 'La société mère doit détenir au moins 95 % du capital de ses filiales.' },

  // ---- UE 6 ----
  { id: 'q-ue6-01', ue: 6, q: 'Trésorerie nette = ?', choices: ['FRNG + BFR', 'FRNG − BFR', 'BFR − FRNG', 'Actif − Passif'], answer: 1, expl: 'TN = FRNG − BFR.' },
  { id: 'q-ue6-02', ue: 6, q: 'Un projet d\'investissement est jugé rentable si sa VAN est…', choices: ['Négative', 'Nulle uniquement', 'Positive', 'Inférieure au taux d\'actualisation'], answer: 2, expl: 'VAN > 0 : les flux actualisés couvrent le capital investi.' },
  { id: 'q-ue6-03', ue: 6, q: 'Investissement 10 000 ; flux 5 000 (an 1) et 6 000 (an 2) ; taux 10 %. VAN ?', choices: ['+1 000 €', '+496 €', '−496 €', '−1 000 €'], answer: 2, expl: '5 000/1,1 + 6 000/1,21 = 4 545 + 4 959 = 9 504 ; VAN = 9 504 − 10 000 ≈ −496 €. Projet à rejeter.' },
  { id: 'q-ue6-04', ue: 6, q: 'Emprunt 100 000 € sur 5 ans à 5 %, annuités constantes. Annuité ?', choices: ['20 000 €', '21 000 €', '23 097 €', '25 000 €'], answer: 2, expl: 'a = 100 000 × 0,05 ÷ (1 − 1,05^-5) ≈ 23 097 €.' },
  { id: 'q-ue6-05', ue: 6, q: 'Stocks 40 000, clients 60 000, fournisseurs 50 000, FRNG 70 000. Trésorerie nette ?', choices: ['20 000 €', '50 000 €', '70 000 €', '120 000 €'], answer: 0, expl: 'BFR = 40 000 + 60 000 − 50 000 = 50 000 ; TN = 70 000 − 50 000 = 20 000 €.' },
  { id: 'q-ue6-06', ue: 6, q: 'CP 600 à 10 %, dettes 400 à 5 % avant impôt, IS 25 %. CMPC ?', choices: ['6,5 %', '7,5 %', '8,0 %', '8,75 %'], answer: 1, expl: '0,6 × 10 % + 0,4 × 5 % × 0,75 = 6 % + 1,5 % = 7,5 %.' },
  { id: 'q-ue6-07', ue: 6, q: 'MEDAF : taux sans risque 3 %, prime de marché 6 %, bêta 1,2. Coût des capitaux propres ?', choices: ['7,2 %', '9 %', '10,2 %', '12 %'], answer: 2, expl: '3 % + 1,2 × 6 % = 10,2 %.' },
  { id: 'q-ue6-08', ue: 6, q: 'Gordon-Shapiro : D1 = 2 €, k = 8 %, g = 3 %. Valeur de l\'action ?', choices: ['25 €', '40 €', '66,7 €', '100 €'], answer: 1, expl: '2 ÷ (0,08 − 0,03) = 40 €.' },
  { id: 'q-ue6-09', ue: 6, q: 'Re = 10 %, i = 6 %, D/CP = 1. Rentabilité financière (avant impôt) ?', choices: ['10 %', '12 %', '14 %', '16 %'], answer: 2, expl: 'Rf = 10 % + (10 % − 6 %) × 1 = 14 %.' },
  { id: 'q-ue6-10', ue: 6, q: 'Investissement 30 000 €, flux constants de 10 000 €/an. DRCI ?', choices: ['2 ans', '3 ans', '4 ans', '5 ans'], answer: 1, expl: '30 000 ÷ 10 000 = 3 ans (hors actualisation).' },
  { id: 'q-ue6-11', ue: 6, q: 'RN 50 000 ; dotations 20 000 ; reprises 5 000 ; VNC cédée 8 000 ; prix de cession 10 000. CAF ?', choices: ['58 000 €', '63 000 €', '65 000 €', '73 000 €'], answer: 1, expl: '50 000 + 20 000 − 5 000 + 8 000 − 10 000 = 63 000 €.' },
  { id: 'q-ue6-12', ue: 6, q: 'Créances clients TTC 90 000 € ; CA TTC 540 000 €. Délai clients (base 360 jours) ?', choices: ['30 jours', '45 jours', '60 jours', '90 jours'], answer: 2, expl: '90 000 ÷ 540 000 × 360 = 60 jours.' },
  { id: 'q-ue6-13', ue: 6, q: 'Le TRI est le taux pour lequel…', choices: ['La VAN est maximale', 'La VAN est nulle', 'Le délai de récupération est nul', 'L\'indice de profitabilité est nul'], answer: 1, expl: 'C\'est le taux d\'actualisation qui annule la VAN.' },
  { id: 'q-ue6-14', ue: 6, q: 'Le ratio de liquidité générale est…', choices: ['Disponibilités / dettes à court terme', 'Actif circulant / dettes à court terme', 'Capitaux propres / dettes', 'CAF / dettes financières'], answer: 1, expl: 'Liquidité générale = actif circulant ÷ dettes à court terme.' },

  // ---- UE 7 ----
  { id: 'q-ue7-01', ue: 7, q: 'Laquelle n\'est PAS l\'une des 5 forces de Porter ?', choices: ['Pouvoir des fournisseurs', 'Menace des substituts', 'Taux de change', 'Menace des nouveaux entrants'], answer: 2, expl: 'Le taux de change relève de l\'analyse PESTEL (environnement économique), pas du modèle de Porter.' },
  { id: 'q-ue7-02', ue: 7, q: 'Qui est à l\'origine de l\'organisation scientifique du travail ?', choices: ['Fayol', 'Mayo', 'Taylor', 'Weber'], answer: 2, expl: 'Taylor : division du travail, étude des temps et des mouvements, salaire au rendement.' },
  { id: 'q-ue7-03', ue: 7, q: 'Un produit à forte croissance mais faible part de marché relative est, selon le BCG, un…', choices: ['Vedette', 'Vache à lait', 'Dilemme', 'Poids mort'], answer: 2, expl: 'C\'est un « point d\'interrogation » (dilemme) : il peut devenir vedette ou poids mort.' },
  { id: 'q-ue7-04', ue: 7, q: 'Un nouveau produit lancé sur un nouveau marché relève, selon Ansoff, de…', choices: ['La pénétration', 'Le développement de marché', 'Le développement de produit', 'La diversification'], answer: 3, expl: 'Nouveaux produits × nouveaux marchés = diversification.' },
  { id: 'q-ue7-05', ue: 7, q: 'Dans la pyramide de Maslow, quel besoin se situe juste au-dessus du besoin de sécurité ?', choices: ['Physiologique', 'Appartenance', 'Estime', 'Accomplissement'], answer: 1, expl: 'Ordre : physiologiques, sécurité, appartenance, estime, accomplissement.' },
  { id: 'q-ue7-06', ue: 7, q: 'Pour Herzberg, le salaire est surtout un facteur…', choices: ['De motivation', 'D\'hygiène', 'D\'accomplissement', 'De pouvoir'], answer: 1, expl: 'Son absence démotive, mais sa présence ne suffit pas à motiver.' },
  { id: 'q-ue7-07', ue: 7, q: 'Quelle configuration de Mintzberg repose sur la standardisation des procédés ?', choices: ['Structure simple', 'Bureaucratie mécaniste', 'Adhocratie', 'Structure divisionnalisée'], answer: 1, expl: 'La bureaucratie mécaniste s\'appuie sur la technostructure et la standardisation des procédés de travail.' },
  { id: 'q-ue7-08', ue: 7, q: 'Quelle stratégie générique consiste à proposer des produits perçus comme uniques ?', choices: ['Domination par les coûts', 'Différenciation', 'Concentration par les coûts', 'Diversification'], answer: 1, expl: 'La différenciation vise une valeur perçue supérieure et justifie un prix plus élevé.' },
  { id: 'q-ue7-09', ue: 7, q: 'Laquelle est une activité de soutien dans la chaîne de valeur de Porter ?', choices: ['Logistique interne', 'Production', 'Marketing et vente', 'Gestion des ressources humaines'], answer: 3, expl: 'La GRH est une activité de soutien, comme l\'infrastructure, la R&D et les approvisionnements.' },
  { id: 'q-ue7-10', ue: 7, q: 'Selon McGregor, la théorie X postule que…', choices: ['Les salariés recherchent l\'autonomie', 'Les salariés évitent le travail et doivent être contrôlés', 'Les salariés sont motivés par l\'accomplissement', 'Le groupe informel est décisif'], answer: 1, expl: 'La théorie X suppose une aversion naturelle pour le travail, d\'où un contrôle étroit.' },
  { id: 'q-ue7-11', ue: 7, q: 'La croissance par rachat d\'une autre entreprise est une croissance…', choices: ['Interne', 'Externe', 'Conjointe', 'Organique'], answer: 1, expl: 'Fusions, acquisitions et prises de participation sont des formes de croissance externe.' },
  { id: 'q-ue7-12', ue: 7, q: 'Quelles sont les trois étapes du changement selon Lewin ?', choices: ['Analyse, décision, contrôle', 'Décristallisation, changement, recristallisation', 'Planifier, faire, vérifier', 'Information, formation, évaluation'], answer: 1, expl: 'On remet en cause les habitudes, on met en œuvre le changement, puis on le stabilise.' },
  { id: 'q-ue7-13', ue: 7, q: 'La théorie de l\'agence étudie…', choices: ['Les conflits entre mandants et mandataires', 'La motivation des salariés', 'La structure matricielle', 'La culture d\'entreprise'], answer: 0, expl: 'Conflits d\'intérêts entre actionnaires (mandants) et dirigeants (mandataires), avec asymétrie d\'information.' },

  // ---- UE 10 ----
  { id: 'q-ue10-01', ue: 10, q: 'Un bien acheté 20 000 € et amorti de 12 000 € est cédé 9 500 €. Résultat de cession ?', choices: ['Plus-value de 1 500 €', 'Moins-value de 1 500 €', 'Plus-value de 9 500 €', 'Moins-value de 8 000 €'], answer: 0, expl: 'VNC = 20 000 − 12 000 = 8 000 €. 9 500 − 8 000 = +1 500 € (plus-value).' },
  { id: 'q-ue10-02', ue: 10, q: 'Quel principe impose de provisionner un risque probable ?', choices: ['Continuité d\'exploitation', 'Prudence', 'Permanence des méthodes', 'Coût historique'], answer: 1, expl: 'Principe de prudence : on tient compte des risques et pertes probables, pas des gains latents.' },
  { id: 'q-ue10-03', ue: 10, q: 'Une charge constatée d\'avance correspond à une charge…', choices: ['Payée sur l\'exercice et relative à l\'exercice suivant', 'À payer relative à l\'exercice', 'Exceptionnelle', 'Non déductible'], answer: 0, expl: 'On la retire des charges de l\'exercice N (compte 486) car elle concerne N+1.' },
  { id: 'q-ue10-04', ue: 10, q: 'Machine de 30 000 € mise en service le 1er avril, amortie 5 ans en linéaire. Annuité de la 1re année ?', choices: ['6 000 €', '4 500 €', '5 000 €', '3 000 €'], answer: 1, expl: '30 000 ÷ 5 = 6 000 € par an ; prorata 9/12 → 4 500 €.' },
  { id: 'q-ue10-05', ue: 10, q: 'Bien de 24 000 €, 5 ans, dégressif, acquis le 1er janvier. Première annuité ?', choices: ['4 800 €', '6 000 €', '8 400 €', '10 800 €'], answer: 2, expl: 'Taux linéaire 20 % × 1,75 = 35 % ; 24 000 × 35 % = 8 400 €.' },
  { id: 'q-ue10-06', ue: 10, q: 'Créance client douteuse de 1 200 € TTC (TVA 20 %), perte probable estimée à 50 %. Dépréciation ?', choices: ['600 €', '500 €', '1 000 €', '1 200 €'], answer: 1, expl: 'La dépréciation se calcule sur le HT : 1 000 × 50 % = 500 €.' },
  { id: 'q-ue10-07', ue: 10, q: 'Assurance annuelle de 1 200 € payée le 1er octobre N. Charge constatée d\'avance au 31/12/N ?', choices: ['300 €', '600 €', '900 €', '1 200 €'], answer: 2, expl: '9 mois sur 12 concernent N+1 : 1 200 × 9/12 = 900 €.' },
  { id: 'q-ue10-08', ue: 10, q: 'Stock de marchandises : SI 10 000, SF 12 500. Quelle écriture de variation de stocks ?', choices: ['Débit 6037 de 2 500 €', 'Crédit 6037 de 2 500 €', 'Crédit 6037 de 12 500 €', 'Débit 37 de 10 000 €'], answer: 1, expl: 'Le stock augmente de 2 500 € : on crédite 6037 (diminution de charges).' },
  { id: 'q-ue10-09', ue: 10, q: 'Machine achetée 50 000 €, amortie 32 000 €, cédée 15 000 €. Résultat de cession ?', choices: ['Moins-value de 3 000 €', 'Plus-value de 3 000 €', 'Moins-value de 18 000 €', 'Plus-value de 15 000 €'], answer: 0, expl: 'VNC = 18 000 € ; 15 000 − 18 000 = −3 000 € (moins-value).' },
  { id: 'q-ue10-10', ue: 10, q: 'Une société détient 55 % des droits de vote d\'une autre. Méthode de consolidation ?', choices: ['Mise en équivalence', 'Intégration proportionnelle', 'Intégration globale', 'Aucune'], answer: 2, expl: 'Contrôle exclusif (plus de 50 % des droits de vote) → intégration globale.' },
  { id: 'q-ue10-11', ue: 10, q: 'Une participation de 25 % avec influence notable est consolidée par…', choices: ['Intégration globale', 'Intégration proportionnelle', 'Mise en équivalence', 'Cumul simple'], answer: 2, expl: 'Influence notable (présumée dès 20 % des droits de vote) → mise en équivalence.' },
  { id: 'q-ue10-12', ue: 10, q: 'Les amortissements dérogatoires (compte 145) figurent…', choices: ['À l\'actif', 'Dans les capitaux propres (provisions réglementées)', 'Dans les dettes fournisseurs', 'Dans les charges à payer'], answer: 1, expl: 'Ce sont des provisions réglementées, rattachées aux capitaux propres.' },
  { id: 'q-ue10-13', ue: 10, q: 'La quote-part de subvention d\'investissement virée au résultat est enregistrée en…', choices: ['Charges exceptionnelles', 'Produits d\'exploitation', 'Autres produits exceptionnels (777)', 'Réserves'], answer: 2, expl: 'Elle est reprise au compte 777 « Quote-part des subventions d\'investissement virée au résultat ».' },
  { id: 'q-ue10-14', ue: 10, q: 'Un écart de conversion actif (compte 476) correspond à…', choices: ['Un gain latent de change', 'Une perte latente de change', 'Un gain réalisé', 'Une provision réglementée'], answer: 1, expl: 'L\'écart de conversion actif constate une perte latente sur créance ou dette en devises, et appelle une provision pour perte de change.' },

  // ---- UE 11 ----
  { id: 'q-ue11-01', ue: 11, q: 'CA = 100 000 €, charges variables = 60 000 €, charges fixes = 30 000 €. Seuil de rentabilité ?', choices: ['30 000 €', '50 000 €', '75 000 €', '90 000 €'], answer: 2, expl: 'Taux de MCV = 40 %. SR = 30 000 ÷ 0,40 = 75 000 €.' },
  { id: 'q-ue11-02', ue: 11, q: 'La marge sur coût variable se calcule par…', choices: ['CA − charges fixes', 'CA − charges variables', 'Résultat + charges variables', 'CA − coût complet'], answer: 1, expl: 'MCV = CA − charges variables.' },
  { id: 'q-ue11-03', ue: 11, q: 'CA 500 000, CV 300 000, CF 120 000. Marge de sécurité ?', choices: ['120 000 €', '200 000 €', '300 000 €', '380 000 €'], answer: 1, expl: 'MCV = 200 000 (40 %), SR = 300 000 ; marge de sécurité = 500 000 − 300 000 = 200 000 €.' },
  { id: 'q-ue11-04', ue: 11, q: 'Même entreprise (CA 500 000, CV 300 000, CF 120 000). Levier opérationnel ?', choices: ['1,5', '2,0', '2,5', '4,0'], answer: 2, expl: 'Résultat = 200 000 − 120 000 = 80 000 ; levier = 200 000 ÷ 80 000 = 2,5.' },
  { id: 'q-ue11-05', ue: 11, q: 'Qr = 1 000 kg à Pr = 5,20 €. Prix standard 5 €. Écart sur prix ?', choices: ['+200 € défavorable', '−200 € favorable', '+520 € défavorable', '0'], answer: 0, expl: '(5,20 − 5) × 1 000 = +200 € : coût réel supérieur, écart défavorable.' },
  { id: 'q-ue11-06', ue: 11, q: 'Qr = 1 000 kg, Qs = 950 kg, Ps = 5 €. Écart sur quantité ?', choices: ['250 € défavorable', '250 € favorable', '50 € défavorable', '4 750 €'], answer: 0, expl: '(1 000 − 950) × 5 = +250 € : consommation excessive, écart défavorable.' },
  { id: 'q-ue11-07', ue: 11, q: 'Activité réelle 800 unités, activité normale 1 000. Coefficient d\'imputation rationnelle ?', choices: ['0,2', '0,8', '1,0', '1,25'], answer: 1, expl: '800 ÷ 1 000 = 0,8 : 80 % des charges fixes sont imputées, 20 % constituent le coût de sous-activité.' },
  { id: 'q-ue11-08', ue: 11, q: 'Quel axe ne figure PAS dans le balanced scorecard ?', choices: ['Financier', 'Clients', 'Juridique', 'Apprentissage organisationnel'], answer: 2, expl: 'Les 4 axes : financier, clients, processus internes, apprentissage organisationnel.' },
  { id: 'q-ue11-09', ue: 11, q: 'Stock initial 100 u à 10 €, entrée 300 u à 12 €. CMUP de fin de période ?', choices: ['11 €', '11,50 €', '11,75 €', '12 €'], answer: 1, expl: '(1 000 + 3 600) ÷ 400 = 11,50 €.' },
  { id: 'q-ue11-10', ue: 11, q: 'Matières 20 000, MOD 15 000, charges indirectes de production 5 000 pour 2 000 unités. Coût de production unitaire ?', choices: ['10 €', '15 €', '20 €', '25 €'], answer: 2, expl: '(20 000 + 15 000 + 5 000) ÷ 2 000 = 20 €.' },
  { id: 'q-ue11-11', ue: 11, q: 'Quel budget est établi en premier dans la chaîne des budgets ?', choices: ['Trésorerie', 'Approvisionnements', 'Ventes', 'Investissements'], answer: 2, expl: 'Les ventes conditionnent la production, les approvisionnements puis la trésorerie.' },
  { id: 'q-ue11-12', ue: 11, q: 'Seuil de rentabilité de 300 000 € pour un CA de 500 000 €. Point mort ?', choices: ['6 mois', '7,2 mois', '8 mois', '9,6 mois'], answer: 1, expl: '300 000 ÷ 500 000 × 12 = 7,2 mois (soit début août environ).' },
  { id: 'q-ue11-13', ue: 11, q: 'Dans le direct costing simple, quelles charges sont imputées aux coûts ?', choices: ['Toutes les charges', 'Seulement les charges variables', 'Seulement les charges fixes', 'Seulement les charges directes'], answer: 1, expl: 'Seules les charges variables sont imputées ; les charges fixes sont traitées globalement.' },
  { id: 'q-ue11-14', ue: 11, q: 'Prix de vente accepté par le marché : 100 €, marge souhaitée : 20 €. Coût cible ?', choices: ['20 €', '80 €', '100 €', '120 €'], answer: 1, expl: 'Coût cible = prix de vente − marge = 100 − 20 = 80 €.' }
];
